function useDemoStore<T>(key: string, initial: T) { const [value, setValue] = useState<T>(initial); const [ready, setReady] = useState(false); useEffect(() => { try { const stored = window.localStorage.getItem(`icenter-admin-${key}`); if (stored) setValue(JSON.parse(stored)); } catch { window.localStorage.removeItem(`icenter-admin-${key}`); } finally { setReady(true); } }, [key]); useEffect(() => { if (ready) { try { window.localStorage.setItem(`icenter-admin-${key}`, JSON.stringify(value)); } catch { /* Browser storage quota is optional for demo state. */ } } }, [key, value, ready]); return [value, setValue] as const; }
function useNotice() { const [notice, setNotice] = useState(""); return { notice, show: (text: string) => { setNotice(text); window.setTimeout(() => setNotice(""), 2600); } }; }
function slugify(value: string) { return value.toLowerCase().trim().replace(/[^a-zа-яё0-9]+/gi, "-").replace(/(^-|-$)/g, ""); }
function descendantsOf(categories: Category[], id: string) { const found = new Set<string>([id]); let changed = true; while (changed) { changed = false; for (const category of categories) if (category.parent && found.has(category.parent) && !found.has(category.id)) { found.add(category.id); changed = true; } } return found; }
function hexToHue(hex: string) { if (!/^#[0-9A-F]{6}$/i.test(hex)) return 210; const n = hex.slice(1); const r = parseInt(n.slice(0, 2), 16) / 255, g = parseInt(n.slice(2, 4), 16) / 255, b = parseInt(n.slice(4, 6), 16) / 255; const max = Math.max(r, g, b), min = Math.min(r, g, b), d = max - min; if (!d) return 210; let h = max === r ? ((g - b) / d) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4; h = Math.round(h * 60); return h < 0 ? h + 360 : h; }
function hexToHsv(hex: string) { if (!/^#[0-9A-F]{6}$/i.test(hex)) return { s: 0.78, v: 0.92 }; const n = hex.slice(1); const r = parseInt(n.slice(0, 2), 16) / 255, g = parseInt(n.slice(2, 4), 16) / 255, b = parseInt(n.slice(4, 6), 16) / 255; const max = Math.max(r, g, b), min = Math.min(r, g, b); return { s: max ? (max - min) / max : 0, v: max }; }
function hsvToHex(h: number, s: number, v: number) { const c = v * s, x = c * (1 - Math.abs((h / 60) % 2 - 1)), m = v - c; const [r, g, b] = h < 60 ? [c, x, 0] : h < 120 ? [x, c, 0] : h < 180 ? [0, c, x] : h < 240 ? [0, x, c] : h < 300 ? [x, 0, c] : [c, 0, x]; return `#${[r, g, b].map(n => Math.round((n + m) * 255).toString(16).padStart(2, "0")).join("").toUpperCase()}`; }
function Shell({ title, subtitle, children, action }: { title: string; subtitle: string; children: React.ReactNode; action?: React.ReactNode }) { return <div className="admin-content admin-workspace"><div className="workspace-head"><div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>{children}</div>; }
function Toolbar({ query, setQuery, placeholder, children }: { query: string; setQuery: (v: string) => void; placeholder: string; children?: React.ReactNode }) { return <div className="workspace-toolbar"><label className="admin-field-search"><Search size={17} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder={placeholder} /></label>{children}</div>; }
function Modal({ title, close, children, save, saveLabel = "Сохранить" }: { title: string; close: () => void; children: React.ReactNode; save: () => void; saveLabel?: string }) { return <div className="admin-modal-backdrop"><section className="admin-modal"><header><h2>{title}</h2><button onClick={close} aria-label="Закрыть"><X size={19} /></button></header><div className="admin-modal-body">{children}</div><footer><button className="admin-secondary" onClick={close}>Отмена</button><button className="admin-primary" onClick={save}>{saveLabel}</button></footer></section></div>; }
function Field({ label, value, setValue, required = false, placeholder = "" }: { label: string; value: string; setValue: (v: string) => void; required?: boolean; placeholder?: string }) { return <label className="admin-form-label">{label}{required && <sup>*</sup>}<input value={value} onChange={e => setValue(e.target.value)} placeholder={placeholder} /></label>; }
function SelectField({ label, value, setValue, options }: { label: string; value: string; setValue: (v: string) => void; options: string[] }) { return <label className="admin-form-label">{label}<select value={value} onChange={e => setValue(e.target.value)}>{options.map(option => <option key={option}>{option}</option>)}</select></label>; }
function Empty({ text = "Ничего не найдено" }: { text?: string }) { return <div className="admin-empty"><Search size={28} /><h2>{text}</h2><p>Измените запрос или добавьте новую запись.</p></div>; }
