function RequestsPage() { const [items] = useDemoStore("requests", initialRequests); const [query, setQuery] = useState(""); const [city, setCity] = useState("Все города"); const [date, setDate] = useState(""); const [selected, setSelected] = useState<Request | null>(null); const [page, setPage] = useState(1); const pageSize = 8; const filtered = items.filter(item => (!query || `${item.id} ${item.name}`.toLowerCase().includes(query.toLowerCase())) && (city === "Все города" || item.city === city) && (!date || item.date.split(".").reverse().join("-") === date)); const pageCount = Math.max(1, Math.ceil(filtered.length / pageSize)); const currentPage = Math.min(page, pageCount); const visible = filtered.slice((currentPage - 1) * pageSize, currentPage * pageSize); useEffect(() => setPage(1), [query, city, date]); return <Shell title="Заявки" subtitle="Просмотр заявок без статусов и жизненного цикла"><Toolbar query={query} setQuery={setQuery} placeholder="Поиск по номеру или клиенту..."><select value={city} onChange={e => setCity(e.target.value)}><option>Все города</option>{cityNames.map(x => <option key={x}>{x}</option>)}</select><input aria-label="Фильтр по дате" type="date" value={date} onChange={e => setDate(e.target.value)} /></Toolbar>{filtered.length ? <><div className="workspace-table panel"><table className="table"><thead><tr><th>№ заявки</th><th>Дата</th><th>Город</th><th>Клиент</th><th>Канал</th><th>Товары</th><th>Сумма</th><th /></tr></thead><tbody>{visible.map(item => <tr key={item.id}><td><strong>{item.id}</strong></td><td>{item.date}</td><td>{item.city}</td><td>{item.name}</td><td>{item.channel}</td><td>{item.items.map(x => x.name).join(", ")}</td><td>{item.total}</td><td><button className="icon-action" onClick={() => setSelected(item)} aria-label="Открыть детали">›</button></td></tr>)}</tbody></table></div><div className="admin-pagination" aria-label="Пагинация заявок"><button className="admin-secondary" disabled={currentPage === 1} onClick={() => setPage(currentPage - 1)}>Назад</button><span>Страница {currentPage} из {pageCount}</span><button className="admin-secondary" disabled={currentPage === pageCount} onClick={() => setPage(currentPage + 1)}>Вперёд</button></div></> : <Empty />}{selected && <Modal title={`Заявка №${selected.id}`} close={() => setSelected(null)} save={() => setSelected(null)} saveLabel="Закрыть"><div className="detail-list"><span>Дата и город: {selected.date}  · {selected.city}</span><span>Клиент: {selected.name}{selected.phone ? ` · ${selected.phone}` : " · не предоставлен"}</span><span>Канал связи: {selected.channel}</span><span>Способ получения: {selected.fulfilment}</span><span>Комментарий: {selected.comment || "не указан"}</span>{selected.items.map(item => <span key={item.name}>Товар: {item.name} ↑ {item.variant} ↓ {item.quantity} шт. · {item.price}</span>)}<strong>Итого: {selected.total}</strong></div></Modal>}</Shell>; }


function makeSku(name: string, attrs: Record<string, string>, used: string[]) {
  const transliteration: Record<string, string> = { "\u0430": "a", "\u0431": "b", "\u0432": "v", "\u0433": "g", "\u0434": "d", "\u0435": "e", "\u0451": "e", "\u0436": "zh", "\u0437": "z", "\u0438": "i", "\u0439": "y", "\u043a": "k", "\u043b": "l", "\u043c": "m", "\u043d": "n", "\u043e": "o", "\u043f": "p", "\u0440": "r", "\u0441": "s", "\u0442": "t", "\u0443": "u", "\u0444": "f", "\u0445": "h", "\u0446": "ts", "\u0447": "ch", "\u0448": "sh", "\u0449": "sch", "\u044a": "", "\u044b": "y", "\u044c": "", "\u044d": "e", "\u044e": "yu", "\u044f": "ya" };
  const ascii = (name + "-" + Object.values(attrs).join("-")).toLowerCase().replace(/[\u0430-\u044f\u0451]/g, x => transliteration[x] || "").replace(/[^a-z0-9]+/g, "-").replace(/(^-|-$)/g, "").toUpperCase().slice(0, 28) || "PRODUCT";
  let suffix = 1;
  let sku = "IC-" + ascii + "-" + String(suffix).padStart(2, "0");
  while (used.includes(sku)) sku = "IC-" + ascii + "-" + String(++suffix).padStart(2, "0");
  return sku;
}

function ProductsStudio() { const [items, setItems] = useDemoStore("products", initialProducts); const [query, setQuery] = useState(""); const [brand, setBrand] = useState("Все бренды"); const [type, setType] = useState("Все типы"); const [category, setCategory] = useState("Все категории"); const [city, setCity] = useState("Все города"); const [scope, setScope] = useState("Активные"); const [editing, setEditing] = useState<Product | null>(null); const [notice, setNotice] = useState(""); const [brands] = useDemoStore("brands", initialBrands); const [types] = useDemoStore("product-types-v2", [{ id: "type-phone", name: "Смартфоны", slug: "smartfony", description: "", image: imageChoices[0], attributes: {} }, { id: "type-tablet", name: "Планшеты", slug: "planshety", description: "", image: imageChoices[2], attributes: {} }]); const [categories] = useDemoStore("categories", initialCategories); const filtered = items.filter(x => `${x.name} ${x.sku} ${x.brand} ${x.category}`.toLowerCase().includes(query.toLowerCase()) && (brand === "Все бренды" || x.brand === brand) && (type === "Все типы" || x.type === type) && (category === "Все категории" || x.category === category) && (scope === "Архив" ? Boolean(x.archived) : !x.archived) && (city === "Все города" || x.variants.some(v => { const offer = v.cities[city]; return offer && (offer.price.trim() || offer.availability !== "Не задано"); }))); const save = (next: Product) => { const saved = { ...next, sku: next.variants[0]?.sku || next.sku }; setItems(prev => prev.some(x => x.id === saved.id) ? prev.map(x => x.id === saved.id ? saved : x) : [...prev, saved]); setEditing(null); setNotice("Изменения сохранены локально в этом браузере"); }; return <Shell title="Товары" subtitle="Товары, реальные варианты и городские цены" action={<button className="admin-primary" onClick={() => setEditing({ id: `product-${Date.now()}`, name: "", sku: "", brand: brands[0]?.name || "", type: types[0]?.name || "", category: categories.find(x => !x.parent)?.name || "", subcategory: "", description: "", images: [], galleries: {}, attributes: [], variants: [] })}><Plus size={17} />Добавить товар</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Название, SKU, бренд или категория..."><select aria-label="Фильтр по бренду" value={brand} onChange={e => setBrand(e.target.value)}><option>Все бренды</option>{Array.from(new Set([...brands.map(x => x.name), ...items.map(x => x.brand)])).filter(Boolean).map(x => <option key={x}>{x}</option>)}</select><select aria-label="Фильтр по типу" value={type} onChange={e => setType(e.target.value)}><option>Все типы</option>{Array.from(new Set([...types.map(x => x.name), ...items.map(x => x.type)])).filter(Boolean).map(x => <option key={x}>{x}</option>)}</select><select aria-label="Фильтр по категории" value={category} onChange={e => setCategory(e.target.value)}><option>Все категории</option>{Array.from(new Set([...categories.map(x => x.name), ...items.map(x => x.category)])).filter(Boolean).map(x => <option key={x}>{x}</option>)}</select><select aria-label="Фильтр по городу" value={city} onChange={e => setCity(e.target.value)}><option>Все города</option>{cityNames.map(x => <option key={x}>{x}</option>)}</select><select aria-label="Фильтр по состоянию" value={scope} onChange={e => setScope(e.target.value)}><option>Активные</option><option>Архив</option></select></Toolbar>{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Фото</th><th>Название / SKU</th><th>Бренд</th><th>Категория</th><th>Варианты</th><th>Доступность</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><img className="admin-thumb" src={item.images[0] || imageChoices[0]} alt={item.name} /></td><td><strong>{item.name || "Без названия"}</strong><small>{item.variants[0]?.sku || item.sku || "SKU появится после добавления варианта"}</small></td><td>{item.brand}</td><td>{item.category}{item.subcategory ? ` / ${item.subcategory}` : ""}</td><td>{item.variants.length}</td><td>{item.variants.length ? "Доступность зависит от города" : "Не настроена"}</td><td><span className="row-actions"><button className="icon-action" onClick={() => setEditing(item)} aria-label="Изменить"><Edit3 size={16} /></button><button className="icon-action" onClick={() => { setItems(prev => prev.map(x => x.id === item.id ? { ...x, archived: !x.archived } : x)); setNotice(item.archived ? "Товар возвращён из архива локально" : "Товар архивирован локально"); }} aria-label={item.archived ? "Вернуть из архива" : "Архивировать"} title={item.archived ? "Вернуть из архива" : "Архивировать"}>{item.archived ? <RotateCcw size={16} /> : <Archive size={16} />}</button></span></td></tr>)}</tbody></table></div> : <Empty text={scope === "Архив" ? "Архив пуст" : undefined} />}{notice && <div className="admin-toast" role="status">{notice}</div>}{editing && <ProductStudioModal product={editing} usedSkus={items.flatMap(x => x.variants.map(v => v.sku))} close={() => setEditing(null)} save={save} />}</Shell>; }


function ProductStudioModal({ product, usedSkus, close, save }: { product: Product; usedSkus: string[]; close: () => void; save: (product: Product) => void }) {
  const [item, setItem] = useState({ ...product, attributes: product.attributes || [], galleries: product.galleries || {} });
  const [attributeName, setAttributeName] = useState("");
  const [attributeValues, setAttributeValues] = useState("");
  const [selection, setSelection] = useState<Record<string, string>>({});
  const [galleryColor, setGalleryColor] = useState("Общая галерея");
  const [galleryImage, setGalleryImage] = useState(imageChoices[0]);
  const [error, setError] = useState("");
  const [categories] = useDemoStore("categories", initialCategories);
  const [brands] = useDemoStore("brands", initialBrands);
  const [media] = useDemoStore("media", initialMedia);
  const [types] = useDemoStore("product-types-v2", [{ id: "type-phone", name: "Смартфоны", slug: "smartfony", description: "", image: imageChoices[0], attributes: {} }, { id: "type-tablet", name: "Планшеты", slug: "planshety", description: "", image: imageChoices[2], attributes: {} }]);
  const images = Array.from(new Set([...imageChoices, ...media.map(x => x.url)]));
  const parentCategories = categories.filter(x => !x.parent);
  const parent = categories.find(x => x.name === item.category);
  const subcategories = categories.filter(x => x.parent === parent?.id);
  const update = (key: keyof Product, value: string) => setItem(prev => ({ ...prev, [key]: value }));
  const addAttribute = () => {
    const name = attributeName.trim();
    const values = Array.from(new Set(attributeValues.split(",").map(x => x.trim()).filter(Boolean)));
    if (!name || !values.length || item.attributes.some(x => x.name.toLowerCase() === name.toLowerCase())) { setError("Введите уникальное имя атрибута и хотя бы одно значение"); return; }
    setItem(prev => ({ ...prev, attributes: [...prev.attributes, { id: `attr-${Date.now()}`, name, values }] }));
    setSelection(prev => ({ ...prev, [name]: values[0] })); setAttributeName(""); setAttributeValues(""); setError("");
  };
  const addVariant = () => {
    const attrs: Record<string, string> = {};
    item.attributes.forEach(attr => { if (selection[attr.name]) attrs[attr.name] = selection[attr.name]; });
    if (!item.attributes.length || Object.keys(attrs).length !== item.attributes.length) { setError("Выберите значение каждого параметра перед созданием варианта"); return; }
    if (item.variants.some(v => Object.keys(attrs).every(key => v.attributes[key] === attrs[key]) && Object.keys(v.attributes).length === Object.keys(attrs).length)) { setError("Такая комбинация уже существует"); return; }
    const sku = makeSku(item.name, attrs, [...usedSkus, ...item.variants.map(v => v.sku)]);
    const cities = Object.fromEntries(cityNames.map(city => [city, { price: "", availability: "Не задано" as Availability }]));
    setItem(prev => ({ ...prev, variants: [...prev.variants, { id: `variant-${Date.now()}`, sku, attributes: attrs, cities }] })); setError("");
  };
  const addGalleryImage = () => setItem(prev => ({ ...prev, images: Array.from(new Set([...prev.images, galleryImage])), galleries: { ...prev.galleries, [galleryColor]: Array.from(new Set([...(prev.galleries[galleryColor] || []), galleryImage])) } }));
  const saveItem = () => {
    if (!item.name.trim() || !item.category || (subcategories.length > 0 && !item.subcategory)) { setError("Заполните название, категорию и применимую подкатегорию"); return; }
    if (!item.variants.length) { setError("Добавьте хотя бы один вариант товара/SKU"); return; }
    if (item.variants.some(v => Object.values(v.cities).some(c => c.price && (!Number.isFinite(Number(c.price)) || Number(c.price) <= 0)))) { setError("Цена должна быть положительным числом или оставаться пустой"); return; }
    save({ ...item, sku: item.variants[0].sku });
  };
  return <Modal title="Редактор товара" close={close} save={saveItem}>
    <Field label="Название" value={item.name} setValue={v => update("name", v)} required />
    <Field label="Описание" value={item.description} setValue={v => update("description", v)} />
    <div className="admin-form-grid">
      <SelectField label="Бренд" value={item.brand} setValue={v => update("brand", v)} options={brands.map(x => x.name)} />
      <SelectField label="Тип товара" value={item.type} setValue={v => update("type", v)} options={types.map((x: { name: string }) => x.name)} />
      <SelectField label="Категория" value={item.category} setValue={v => setItem(prev => ({ ...prev, category: v, subcategory: "" }))} options={parentCategories.map(x => x.name)} />
      {subcategories.length > 0 && <SelectField label="Подкатегория" value={item.subcategory || "Выберите подкатегорию"} setValue={v => update("subcategory", v)} options={["Выберите подкатегорию", ...subcategories.map(x => x.name)]} />}
    </div>
    <div className="admin-readonly">SKU: <strong>{item.variants[0]?.sku || "создаётся после добавления варианта"}</strong><span>автоматический, уникальный и стабильный</span></div>
    <section className="variant-editor"><h3>Галерея по цветам</h3><div className="admin-form-grid"><SelectField label="Цвет галереи" value={galleryColor} setValue={setGalleryColor} options={["Общая галерея", ...(item.attributes.find(x => x.name.toLowerCase() === "цвет")?.values || [])]} /><SelectField label="Изображение" value={galleryImage} setValue={setGalleryImage} options={images} /></div><button className="admin-secondary" type="button" onClick={addGalleryImage}><Plus size={15} />Добавить фото</button>{Object.entries(item.galleries).map(([color, list]) => <div className="gallery-line" key={color}><b>{color}</b>{list.map(src => <span key={src}><img src={src} alt="" />{src}<button className="icon-action danger" onClick={() => setItem(prev => ({ ...prev, galleries: { ...prev.galleries, [color]: prev.galleries[color].filter(x => x !== src) }, images: prev.images.filter(x => x !== src) }))}><X size={14} /></button></span>)}</div>)}</section>
    <section className="variant-editor"><h3>Параметры и значения</h3><div className="admin-form-grid"><Field label="Название параметра" value={attributeName} setValue={setAttributeName} placeholder="Цвет, память, SIM, RAM..." /><Field label="Значения через запятую" value={attributeValues} setValue={setAttributeValues} placeholder="256 ГБ, 512 ГБ" /></div><button type="button" className="admin-secondary" onClick={addAttribute}><Plus size={15} />Добавить параметр</button>{item.attributes.map(attr => <div className="attribute-card" key={attr.id}><div><strong>{attr.name}</strong><span>{attr.values.join(" · ")}</span></div><button className="icon-action danger" onClick={() => { if (window.confirm("Удаление атрибута изменит комбинации. Продолжить?")) setItem(prev => ({ ...prev, attributes: prev.attributes.filter(x => x.id !== attr.id), variants: prev.variants.map(v => { const attrs = { ...v.attributes }; delete attrs[attr.name]; return { ...v, attributes: attrs }; }) })); }}><Trash2 size={15} /></button></div>)}<div className="admin-form-grid">{item.attributes.map(attr => <SelectField key={attr.id} label={attr.name} value={selection[attr.name] || attr.values[0]} setValue={v => setSelection(prev => ({ ...prev, [attr.name]: v }))} options={attr.values} />)}</div><button type="button" className="admin-primary" onClick={addVariant}><Plus size={15} />Добавить вариант / SKU</button>{item.variants.map(variant => <article className="variant-row" key={variant.id}><div className="variant-sku"><strong>{Object.entries(variant.attributes).map(([name, value]) => `${name}: ${value}`).join(" · ")}</strong><code>{variant.sku}</code><button className="icon-action danger" onClick={() => { if (window.confirm("Удалить вариант только из демо-данных?")) setItem(prev => ({ ...prev, variants: prev.variants.filter(x => x.id !== variant.id) })); }}><Trash2 size={15} /></button></div>{cityNames.map(city => <div className="city-price" key={city}><span>{city}</span><input aria-label={`Цена для города ${city}`} inputMode="decimal" value={variant.cities[city]?.price || ""} onChange={e => setItem(prev => ({ ...prev, variants: prev.variants.map(v => v.id === variant.id ? { ...v, cities: { ...v.cities, [city]: { ...v.cities[city], price: e.target.value } } } : v) }))} placeholder="Уточнить цену" /><select value={variant.cities[city]?.availability || "Не задано"} onChange={e => setItem(prev => ({ ...prev, variants: prev.variants.map(v => v.id === variant.id ? { ...v, cities: { ...v.cities, [city]: { ...v.cities[city], availability: e.target.value as Availability } } } : v) }))}><option>Не задано</option><option>В наличии</option><option>Под заказ · 1–2 дня</option></select></div>)}</article>)}</section>
    {error && <p className="form-error" role="alert">{error}</p>}<p className="admin-note">Демо-изменения хранятся локально. Цены и доступность оставлены неподтверждёнными по умолчанию.</p>
  </Modal>;
}

function CategoriesPage() { const [items, setItems] = useDemoStore("categories", initialCategories); const [products] = useDemoStore("products", initialProducts); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<Category | null>(null); const filtered = items.filter(x => x.name.toLowerCase().includes(query.toLowerCase())).sort((a, b) => a.order - b.order); const save = (item: Category) => { const slug = item.slug || slugify(item.name); const blocked = descendantsOf(items, item.id); if (item.parent && blocked.has(item.parent)) { window.alert("Нельзя назначить родителем себя или дочернюю категорию."); return; } if (items.some(x => x.id !== item.id && x.slug === slug)) { window.alert("Slug уже используется другой категорией."); return; } setItems(prev => prev.some(x => x.id === item.id) ? prev.map(x => x.id === item.id ? { ...item, slug } : x) : [...prev, { ...item, slug }]); setEditing(null); }; return <Shell title="Категории" subtitle="Иерархия и навигация каталога" action={<button className="admin-primary" onClick={() => setEditing({ id: `cat-${Date.now()}`, name: "", slug: "", parent: "", order: items.length + 1, visible: true, image: imageChoices[0] })}><Plus size={17} />Добавить категорию</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск категорий..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Название</th><th>Slug</th><th>Родитель</th><th>Порядок</th><th>Видимость</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><strong style={{ paddingLeft: item.parent ? 24 : 0 }}>{item.parent ? "? " : ""}{item.name}</strong></td><td>{item.slug}</td><td>{items.find(x => x.id === item.parent)?.name || "Корень"}</td><td>{item.order}</td><td>{item.visible ? "Видима" : "Скрыта"}</td><td><Actions onEdit={() => setEditing(item)} onDelete={() => { const hasChildren = items.some(x => x.parent === item.id); const hasProducts = products.some(x => x.category === item.name || x.subcategory === item.name); if (hasChildren || hasProducts) { window.alert("Удаление заблокировано: с категорией связаны подкатегории или товары."); return; } if (window.confirm("Удалить категорию локально?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>)}</tbody></table></div> : <Empty />}{editing && <CategoryModal item={editing} items={items} close={() => setEditing(null)} save={save} />}</Shell>; }
function CategoryModal({ item, items, close, save }: { item: Category; items: Category[]; close: () => void; save: (item: Category) => void }) { const [value, setValue] = useState(item); const [error, setError] = useState(""); const blockedParents = descendantsOf(items, item.id); return <Modal title="Категория" close={close} save={() => { if (!value.name.trim()) { setError("Введите название категории"); return; } if (value.parent && blockedParents.has(value.parent)) { setError("Нельзя выбрать себя или дочернюю категорию"); return; } save({ ...value, slug: value.slug || slugify(value.name) }); }}><Field label="Название" value={value.name} setValue={name => setValue({ ...value, name, slug: value.slug || slugify(name) })} required /><div className="admin-readonly">Slug: <strong>{value.slug || slugify(value.name)}</strong><span>формируется автоматически</span></div><label className="admin-form-label">Родительская категория<select value={value.parent} onChange={e => setValue({ ...value, parent: e.target.value })}><option value="">Корень</option>{items.filter(x => !blockedParents.has(x.id)).map(x => <option key={x.id} value={x.id}>{x.name}</option>)}</select></label><SelectField label="Изображение" value={value.image} setValue={image => setValue({ ...value, image })} options={imageChoices} /><Field label="Порядок" value={String(value.order)} setValue={v => setValue({ ...value, order: Number(v) || 0 })} /><label className="admin-check"><input type="checkbox" checked={value.visible} onChange={e => setValue({ ...value, visible: e.target.checked })} />Видима в каталоге</label>{error && <p className="form-error" role="alert">{error}</p>}</Modal>; }

function BrandsPage() { const [items, setItems] = useDemoStore("brands", initialBrands); const [products] = useDemoStore("products", initialProducts); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<Brand | null>(null); const filtered = items.filter(x => x.name.toLowerCase().includes(query.toLowerCase())).sort((a, b) => a.order - b.order); return <Shell title="Бренды" subtitle="Бренды каталога · без поля сайта" action={<button className="admin-primary" onClick={() => setEditing({ id: `brand-${Date.now()}`, name: "", description: "", logo: imageChoices[0], order: items.length + 1 })}><Plus size={17} />Добавить бренд</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск по названию бренда..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Логотип</th><th>Название</th><th>Товары</th><th>Описание</th><th>Порядок</th><th /></tr></thead><tbody>{filtered.map(item => { const linked = products.filter(x => x.brand === item.name).length; return <tr key={item.id}><td><img className="admin-logo-thumb" src={item.logo} alt={item.name} /></td><td><strong>{item.name || "Без названия"}</strong></td><td>{linked}</td><td>{item.description || "Не указано"}</td><td>{item.order}</td><td><Actions onEdit={() => setEditing(item)} onDelete={() => { if (linked) { window.alert("Удаление заблокировано: сначала назначьте товарам другой бренд."); return; } if (window.confirm("Удалить бренд локально?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>; })}</tbody></table></div> : <Empty />}{editing && <Modal title="Бренд" close={() => setEditing(null)} save={() => { const name = editing.name.trim(); if (!name) return; if (items.some(x => x.id !== editing.id && x.name.toLowerCase() === name.toLowerCase())) { window.alert("Бренд с таким названием уже есть."); return; } const oldName = items.find(x => x.id === editing.id)?.name; if (oldName && oldName !== name && products.some(x => x.brand === oldName)) { window.alert("Нельзя переименовать бренд, пока он используется товарами."); return; } setItems(prev => prev.some(x => x.id === editing.id) ? prev.map(x => x.id === editing.id ? { ...editing, name } : x) : [...prev, { ...editing, name }]); setEditing(null); }}><Field label="Название" value={editing.name} setValue={name => setEditing({ ...editing, name })} required /><Field label="Описание" value={editing.description} setValue={description => setEditing({ ...editing, description })} /><SelectField label="Логотип" value={editing.logo} setValue={logo => setEditing({ ...editing, logo })} options={imageChoices} /><Field label="Порядок" value={String(editing.order)} setValue={order => setEditing({ ...editing, order: Number(order) || 0 })} /></Modal>}</Shell>; }

function ColorsPage() { const [items, setItems] = useDemoStore("colors", initialColors); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<Color | null>(null); const filtered = items.filter(x => `${x.name} ${x.hex}`.toLowerCase().includes(query.toLowerCase())); return <Shell title="Цвета" subtitle="Каталог цветов и HEX-параметры" action={<button className="admin-primary" onClick={() => setEditing({ id: `color-${Date.now()}`, name: "", hex: "#007AFF", order: items.length + 1 })}><Plus size={17} />Добавить цвет</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск по цвету или HEX..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Цвет</th><th>Название</th><th>HEX</th><th>Порядок</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><i className="admin-color-dot" style={{ background: item.hex }} /></td><td>{item.name || "Без названия"}</td><td>{item.hex}</td><td>{item.order}</td><td><Actions onEdit={() => setEditing(item)} onDelete={() => { if (window.confirm("Удалить цвет локально?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>)}</tbody></table></div> : <Empty />}{editing && <ColorModal item={editing} close={() => setEditing(null)} save={item => { setItems(prev => prev.some(x => x.id === item.id) ? prev.map(x => x.id === item.id ? item : x) : [...prev, item]); setEditing(null); }} />}</Shell>; }
function ColorModal({ item, close, save }: { item: Color; close: () => void; save: (item: Color) => void }) { const initial = hexToHsv(item.hex); const [value, setValue] = useState(item); const [error, setError] = useState(""); const [hue, setHue] = useState(hexToHue(item.hex)); const [saturation, setSaturation] = useState(initial.s); const [brightness, setBrightness] = useState(initial.v); const setHex = (hex: string) => { const normalized = (hex.startsWith("#") ? hex : `#${hex}`).toUpperCase(); if (/^#[0-9A-F]{6}$/.test(normalized)) { const hsv = hexToHsv(normalized); setHue(hexToHue(normalized)); setSaturation(hsv.s); setBrightness(hsv.v); } setValue(prev => ({ ...prev, hex: normalized })); }; const choosePalette = (event: React.MouseEvent<HTMLDivElement>) => { const rect = event.currentTarget.getBoundingClientRect(); const nextSaturation = Math.max(0, Math.min(1, (event.clientX - rect.left) / rect.width)); const nextBrightness = Math.max(0, Math.min(1, 1 - (event.clientY - rect.top) / rect.height)); setSaturation(nextSaturation); setBrightness(nextBrightness); setHex(hsvToHex(hue, nextSaturation, nextBrightness)); }; const fromHue = (nextHue: number) => { setHue(nextHue); setHex(hsvToHex(nextHue, saturation, brightness)); }; return <Modal title="Цвет" close={close} save={() => { if (!/^#[0-9A-F]{6}$/i.test(value.hex)) { setError("HEX должен быть в формате #RRGGBB"); return; } if (!value.name.trim()) { setError("Укажите название цвета"); return; } save(value); }}><label className="admin-form-label">Предпросмотр<input className="color-picker" type="color" value={/^#[0-9A-F]{6}$/i.test(value.hex) ? value.hex : "#007AFF"} onChange={e => setHex(e.target.value)} /></label><label className="admin-form-label">Палитра оттенка<div className="color-palette" style={{ background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, hsl(${hue} 100% 50%))` }} onClick={choosePalette} /></label><label className="admin-form-label">Оттенок (hue)<input type="range" min="0" max="360" value={hue} onChange={e => fromHue(Number(e.target.value))} /></label><Field label="HEX" value={value.hex} setValue={setHex} required /><Field label="Название цвета" value={value.name} setValue={name => setValue(prev => ({ ...prev, name }))} required /><Field label="Порядок" value={String(value.order)} setValue={order => setValue(prev => ({ ...prev, order: Number(order) || 0 }))} />{error && <p className="form-error">{error}</p>}</Modal>; }

function ProductTypesPage() { const [items, setItems] = useDemoStore("product-types", [{ id: "type-phone", name: "Смартфоны", slug: "smartfony", description: "", image: imageChoices[0] }, { id: "type-tablet", name: "Планшеты", slug: "planshety", description: "", image: imageChoices[2] }]); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<any | null>(null); const filtered = items.filter(x => x.name.toLowerCase().includes(query.toLowerCase())); return <Shell title="Типы товаров" subtitle="Группы атрибутов и каталога" action={<button className="admin-primary" onClick={() => setEditing({ id: `type-${Date.now()}`, name: "", slug: "", description: "", image: imageChoices[0] })}><Plus size={17} />Добавить тип</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск типов товаров..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Изображение</th><th>Тип</th><th>Slug</th><th>Описание</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><img className="admin-thumb" src={item.image} alt={item.name} /></td><td>{item.name}</td><td>{item.slug}</td><td>{item.description || "Не указано"}</td><td><Actions onEdit={() => setEditing(item)} onDelete={() => { if (window.confirm("Удалить тип локально?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>)}</tbody></table></div> : <Empty />}{editing && <Modal title="Тип товара" close={() => setEditing(null)} save={() => { if (!editing.name.trim()) return; const next = { ...editing, slug: editing.slug || slugify(editing.name) }; setItems(prev => prev.some(x => x.id === next.id) ? prev.map(x => x.id === next.id ? next : x) : [...prev, next]); setEditing(null); }}><Field label="Название" value={editing.name} setValue={name => setEditing({ ...editing, name, slug: editing.slug || slugify(name) })} required /><div className="admin-readonly">Slug: <strong>{editing.slug || slugify(editing.name)}</strong></div><Field label="Описание" value={editing.description} setValue={description => setEditing({ ...editing, description })} /><SelectField label="Изображение" value={editing.image} setValue={image => setEditing({ ...editing, image })} options={imageChoices} /></Modal>}</Shell>; }

function ProductTypesStudio() { type ProductTypeDemo = { id: string; name: string; slug: string; description: string; image: string; attributes: Record<string, string[]> }; const [items, setItems] = useDemoStore<ProductTypeDemo[]>("product-types-v2", [{ id: "type-phone", name: "Смартфоны", slug: "smartfony", description: "", image: imageChoices[0], attributes: { "Цвет": ["Натуральный титан"], "Память": ["256 ГБ", "512 ГБ"], SIM: ["eSIM"] } }, { id: "type-tablet", name: "Планшеты", slug: "planshety", description: "", image: imageChoices[2], attributes: { "Диагональ": ["11 дюймов", "13 дюймов"], "Подключение": ["Wi-Fi", "Wi-Fi + Cellular"] } }]); const [products] = useDemoStore("products", initialProducts); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<ProductTypeDemo | null>(null); const [attribute, setAttribute] = useState(""); const [values, setValues] = useState(""); const filtered = items.filter(x => x.name.toLowerCase().includes(query.toLowerCase())); const update = (next: ProductTypeDemo) => { setItems(prev => prev.some(x => x.id === next.id) ? prev.map(x => x.id === next.id ? next : x) : [...prev, next]); setEditing(null); }; return <Shell title="Типы товаров" subtitle="Типы каталога и произвольные атрибуты" action={<button className="admin-primary" onClick={() => { setEditing({ id: `type-${Date.now()}`, name: "", slug: "", description: "", image: imageChoices[0], attributes: {} }); setAttribute(""); setValues(""); }}><Plus size={17} />Добавить тип</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск типов товаров..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Изображение</th><th>Тип / slug</th><th>Атрибуты</th><th>Описание</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td><img className="admin-thumb" src={item.image} alt={item.name} /></td><td><strong>{item.name}</strong><small>{item.slug}</small></td><td>{Object.keys(item.attributes).join(", ") || "Не заданы"}</td><td>{item.description || "Не указано"}</td><td><Actions onEdit={() => { setEditing(item); setAttribute(""); setValues(""); }} onDelete={() => { const linked = products.some(p => p.type === item.name); if (linked) { window.alert("Тип связан с демо-товаром; удаление заблокировано."); return; } if (window.confirm("Удалить тип только из demo-данных?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>)}</tbody></table></div> : <Empty />}{editing && <Modal title="Тип товара и параметры" close={() => setEditing(null)} save={() => { if (!editing.name.trim()) return; const slug = editing.slug || slugify(editing.name); if (items.some(x => x.id !== editing.id && x.slug === slug)) { window.alert("Такой slug уже существует."); return; } update({ ...editing, slug }); }}><Field label="Название" value={editing.name} setValue={name => setEditing({ ...editing, name, slug: editing.slug || slugify(name) })} required /><div className="admin-readonly">Slug: <strong>{editing.slug || slugify(editing.name)}</strong><span>автоматически</span></div><Field label="Описание" value={editing.description} setValue={description => setEditing({ ...editing, description })} /><SelectField label="Изображение" value={editing.image} setValue={image => setEditing({ ...editing, image })} options={imageChoices} /><h3>Применимые атрибуты</h3><div className="admin-form-grid"><Field label="Название атрибута" value={attribute} setValue={setAttribute} placeholder="Например: Поколение" /><Field label="Значения через запятую" value={values} setValue={setValues} placeholder="Например: Wi-Fi, Wi-Fi + Cellular" /></div><button className="admin-secondary" onClick={() => { const name = attribute.trim(); const list = Array.from(new Set(values.split(",").map(x => x.trim()).filter(Boolean))); if (name && list.length) { setEditing({ ...editing, attributes: { ...editing.attributes, [name]: list } }); setAttribute(""); setValues(""); } }}>Добавить атрибут</button>{Object.entries(editing.attributes).map(([name, vals]) => <div className="attribute-card" key={name}><div><strong>{name}</strong><span>{vals.join(" · ")}</span></div><button className="icon-action danger" onClick={() => { const next = { ...editing.attributes }; delete next[name]; setEditing({ ...editing, attributes: next }); }}><Trash2 size={15} /></button></div>)}</Modal>}</Shell>; }

function CitiesPage() { const [items, setItems] = useDemoStore("cities", initialCities); const [editing, setEditing] = useState<City | null>(null); return <Shell title="Города" subtitle="Контакты, самовывоз и часовые пояса"><div className="city-cards">{items.map(item => <article className="panel city-card" key={item.id}><h2>{item.name}</h2><span>{item.active ? "Активен" : "Неактивен"}</span><p>{item.address || "Адрес не задан"}</p><p>{item.phone || "Телефон не задан"}</p><Actions onEdit={() => setEditing(item)} /></article>)}</div>{editing && <Modal title={`Город: ${editing.name}`} close={() => setEditing(null)} save={() => { setItems(prev => prev.map(x => x.id === editing.id ? editing : x)); setEditing(null); }}><Field label="Адрес / самовывоз" value={editing.address} setValue={address => setEditing({ ...editing, address })} /><Field label="Телефон" value={editing.phone} setValue={phone => setEditing({ ...editing, phone })} /><Field label="График работы" value={editing.hours} setValue={hours => setEditing({ ...editing, hours })} /><Field label="Социальные сети" value={editing.socials} setValue={socials => setEditing({ ...editing, socials })} /><Field label="Часовой пояс" value={editing.timezone} setValue={timezone => setEditing({ ...editing, timezone })} /><label className="admin-check"><input type="checkbox" checked={editing.active} onChange={e => setEditing({ ...editing, active: e.target.checked })} />Город активен</label><p className="admin-note">Контактные значения пусты намеренно: реальные данные не предоставлены.</p></Modal>}</Shell>; }

function BannersPage() { const [items, setItems] = useDemoStore("banners", initialBanners); const [editing, setEditing] = useState<Banner | null>(null); return <Shell title="Баннеры" subtitle="Предустановленные слоты главной страницы"><div className="workspace-table panel"><table className="table"><thead><tr><th>Превью</th><th>Название / слот</th><th>CTA / ссылка</th><th>Порядок</th><th>Активность</th><th /></tr></thead><tbody>{items.map(item => <tr key={item.id}><td><img className="banner-thumb" src={item.image} alt={item.name} /></td><td><strong>{item.name}</strong><small>{item.slot}</small></td><td>{item.cta || "Не задано"}<small>{item.url || ""}</small></td><td>{item.order}</td><td>{item.active ? "Активен" : "Неактивен"}</td><td><Actions onEdit={() => setEditing(item)} /></td></tr>)}</tbody></table></div>{editing && <Modal title="Баннер" close={() => setEditing(null)} save={() => { if (editing.url && !editing.url.startsWith("/")) { window.alert("Ссылка должна начинаться со слеша, например /catalog."); return; } setItems(prev => prev.map(x => x.id === editing.id ? editing : x)); setEditing(null); }}><div className="banner-preview"><img src={editing.image} alt="Предпросмотр desktop" /><img src={editing.mobileImage} alt="Предпросмотр mobile" /></div><SelectField label="Desktop изображение" value={editing.image} setValue={image => setEditing({ ...editing, image })} options={imageChoices} /><SelectField label="Mobile изображение" value={editing.mobileImage} setValue={mobileImage => setEditing({ ...editing, mobileImage })} options={imageChoices} /><Field label="Заголовок" value={editing.name} setValue={name => setEditing({ ...editing, name })} required /><Field label="Описание" value={editing.description} setValue={description => setEditing({ ...editing, description })} /><Field label="CTA" value={editing.cta} setValue={cta => setEditing({ ...editing, cta })} /><Field label="Ссылка" value={editing.url} setValue={url => setEditing({ ...editing, url })} placeholder="/catalog/..." /><Field label="Порядок" value={String(editing.order)} setValue={order => setEditing({ ...editing, order: Number(order) || 0 })} /><label className="admin-check"><input type="checkbox" checked={editing.active} onChange={e => setEditing({ ...editing, active: e.target.checked })} />Баннер активен</label><p className="admin-note">Размер hero: 1920×600 px. Мобильное изображение задаётся отдельно.</p></Modal>}</Shell>; }

function BestOffersPage() { const [items, setItems] = useDemoStore("best-offers", ["iPhone 18 Pro", "AirPods Pro 3"]); const [query, setQuery] = useState(""); const available = initialProducts.map(x => x.name).filter(x => !items.includes(x) && x.toLowerCase().includes(query.toLowerCase())); return <Shell title="Лучшие предложения" subtitle="Выбранные товары каталога · без дублирования цен" action={<button className="admin-primary" onClick={() => { const first = available[0]; if (first) setItems(prev => [...prev, first]); }}><Plus size={17} />Добавить товар</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск товара для добавления..." />{items.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Порядок</th><th>Товар</th><th>Цена</th><th>Активность</th><th /></tr></thead><tbody>{items.map((name, i) => <tr key={name}><td><button className="icon-action" disabled={i === 0} onClick={() => setItems(prev => prev.map((x, n) => n === i - 1 ? name : n === i ? prev[i - 1] : x))}>^</button>{i + 1}<button className="icon-action" disabled={i === items.length - 1} onClick={() => setItems(prev => prev.map((x, n) => n === i + 1 ? name : n === i ? prev[i + 1] : x))}>v</button></td><td>{name}</td><td>Уточнить цену</td><td>Активно</td><td><button className="icon-action danger" onClick={() => setItems(prev => prev.filter(x => x !== name))}><Trash2 size={16} /></button></td></tr>)}</tbody></table></div> : <Empty text="Нет выбранных товаров" />}</Shell>; }

type BestOffer = { id: string; product: string; active: boolean };
function BestOffersStudio() { const [offers, setOffers] = useDemoStore<BestOffer[]>("best-offers-v2", initialProducts.slice(0, 2).map(x => ({ id: `offer-${x.id}`, product: x.name, active: true }))); const [catalog] = useDemoStore("products", initialProducts); const [query, setQuery] = useState(""); const available = catalog.filter(product => !offers.some(offer => offer.product === product.name) && product.name.toLowerCase().includes(query.toLowerCase())); const move = (index: number, delta: number) => { const target = index + delta; if (target < 0 || target >= offers.length) return; setOffers(prev => { const next = [...prev]; [next[index], next[target]] = [next[target], next[index]]; return next; }); }; return <Shell title="Лучшие предложения" subtitle="Только существующие товары каталога · без периода и дублирования цен"><Toolbar query={query} setQuery={setQuery} placeholder="Поиск товара для добавления..." /><div className="offer-picker">{available.slice(0, 5).map(product => <button className="admin-secondary" key={product.id} onClick={() => setOffers(prev => [...prev, { id: `offer-${product.id}`, product: product.name, active: true }])}><Plus size={15} />{product.name}</button>)}{!available.length && <span className="admin-note">Подходящих товаров нет</span>}</div>{offers.length ? <div className="best-offers-grid">{offers.map((offer, index) => { const product = catalog.find(x => x.name === offer.product); return <article className="panel best-offer" key={offer.id}><img src={product?.images[0] || imageChoices[0]} alt={offer.product} /><div className="best-offer-content"><strong>{offer.product}</strong><span>Уточнить цену</span><span>{offer.active ? "Активно" : "Неактивно"}</span></div><div className="best-offer-actions"><button className="icon-action" disabled={index === 0} onClick={() => move(index, -1)} aria-label="Переместить вверх">^</button><button className="icon-action" disabled={index === offers.length - 1} onClick={() => move(index, 1)} aria-label="Переместить вниз">v</button><button className="admin-secondary" onClick={() => setOffers(prev => prev.map(x => x.id === offer.id ? { ...x, active: !x.active } : x))}>{offer.active ? "Скрыть" : "Показать"}</button><button className="icon-action danger" onClick={() => { if (window.confirm("Убрать товар из лучших предложений локально?")) setOffers(prev => prev.filter(x => x.id !== offer.id)); }} aria-label="Удалить"> <Trash2 size={16}/></button></div></article>; })}</div> : <Empty text="Нет выбранных товаров" />}</Shell>; }

function EmployeesPage() { const [items, setItems] = useDemoStore("employees", initialEmployees); const [query, setQuery] = useState(""); const [editing, setEditing] = useState<Employee | null>(null); const filtered = items.filter(x => `${x.firstName} ${x.lastName} ${x.email}`.toLowerCase().includes(query.toLowerCase())); return <Shell title="Сотрудники" subtitle="Роли и доступ по городам · только демонстрационные записи" action={<button className="admin-primary" onClick={() => setEditing({ id: `employee-${Date.now()}`, firstName: "", lastName: "", email: "", phone: "", role: "Manager", cities: [cityNames[0]], canPrice: false, canAvailability: false, active: true })}><Plus size={17} />Добавить сотрудника</button>}><Toolbar query={query} setQuery={setQuery} placeholder="Поиск по имени или email..." />{filtered.length ? <div className="workspace-table panel"><table className="table"><thead><tr><th>Сотрудник</th><th>Email</th><th>Роль</th><th>Города</th><th>Активность</th><th /></tr></thead><tbody>{filtered.map(item => <tr key={item.id}><td>{item.firstName} {item.lastName}</td><td>{item.email || "Не указан"}</td><td>{item.role}</td><td>{item.role === "Admin" ? "Все города" : item.cities.join(", ")}</td><td>{item.active ? "Активен" : "Неактивен"}</td><td><Actions onEdit={() => setEditing(item)} onDelete={() => { if (window.confirm("Удалить сотрудника локально?")) setItems(prev => prev.filter(x => x.id !== item.id)); }} /></td></tr>)}</tbody></table></div> : <Empty />}{editing && <EmployeeStudioModal item={editing} close={() => setEditing(null)} save={item => { setItems(prev => prev.some(x => x.id === item.id) ? prev.map(x => x.id === item.id ? item : x) : [...prev, item]); setEditing(null); }} />}</Shell>; }
function EmployeeStudioModal({ item, close, save }: { item: Employee; close: () => void; save: (item: Employee) => void }) { const [value, setValue] = useState(item); const [error, setError] = useState(""); return <Modal title="Сотрудник" close={close} save={() => { if (!value.firstName.trim() || !value.email.includes("@")) { setError("Укажите имя и корректный email"); return; } if (value.role === "Manager" && !value.cities.length) { setError("Назначьте менеджеру хотя бы один город"); return; } save(value); }}><div className="admin-form-grid"><Field label="Имя" value={value.firstName} setValue={firstName => setValue({ ...value, firstName })} required /><Field label="Фамилия" value={value.lastName} setValue={lastName => setValue({ ...value, lastName })} /></div><Field label="Email" value={value.email} setValue={email => setValue({ ...value, email })} required /><Field label="Телефон" value={value.phone} setValue={phone => setValue({ ...value, phone })} /><SelectField label="Роль" value={value.role} setValue={role => setValue({ ...value, role: role as Employee["role"], cities: role === "Admin" ? cityNames : value.cities })} options={["Admin", "Manager"]} />{value.role === "Manager" && <label className="admin-form-label">Доступные города<select multiple value={value.cities} onChange={e => setValue({ ...value, cities: Array.from(e.target.selectedOptions, option => option.value) })}>{cityNames.map(city => <option key={city}>{city}</option>)}</select></label>}<label className="admin-check"><input type="checkbox" checked={value.canPrice} onChange={e => setValue({ ...value, canPrice: e.target.checked })} />Может изменять цены</label><label className="admin-check"><input type="checkbox" checked={value.canAvailability} onChange={e => setValue({ ...value, canAvailability: e.target.checked })} />Может изменять доступность</label><label className="admin-check"><input type="checkbox" checked={value.active} onChange={e => setValue({ ...value, active: e.target.checked })} />Сотрудник активен</label>{error && <p className="form-error" role="alert">{error}</p>}</Modal>; }
function EmployeeModal({ item, close, save }: { item: Employee; close: () => void; save: (item: Employee) => void }) { const [value, setValue] = useState(item); return <Modal title="Сотрудник" close={close} save={() => save(value)}><div className="admin-form-grid"><Field label="Имя" value={value.firstName} setValue={firstName => setValue({ ...value, firstName })} required /><Field label="Фамилия" value={value.lastName} setValue={lastName => setValue({ ...value, lastName })} /></div><Field label="Email" value={value.email} setValue={email => setValue({ ...value, email })} required /><Field label="Телефон" value={value.phone} setValue={phone => setValue({ ...value, phone })} /><SelectField label="Роль" value={value.role} setValue={role => setValue({ ...value, role: role as Employee["role"], cities: role === "Admin" ? cityNames : value.cities })} options={["Admin", "Manager"]} />{value.role === "Manager" && <label className="admin-form-label">Доступные города<select multiple value={value.cities} onChange={e => setValue({ ...value, cities: Array.from(e.target.selectedOptions, option => option.value) })}>{cityNames.map(city => <option key={city}>{city}</option>)}</select></label>}<label className="admin-check"><input type="checkbox" checked={value.canPrice} onChange={e => setValue({ ...value, canPrice: e.target.checked })} />Может изменять цены</label><label className="admin-check"><input type="checkbox" checked={value.canAvailability} onChange={e => setValue({ ...value, canAvailability: e.target.checked })} />Может изменять доступность</label><label className="admin-check"><input type="checkbox" checked={value.active} onChange={e => setValue({ ...value, active: e.target.checked })} />Сотрудник активен</label></Modal>; }

function SettingsPage() { const [value, setValue] = useDemoStore("settings", { name: "iCenter", description: "", defaultCity: "Самара" }); return <Shell title="Настройки сайта" subtitle="Только базовые глобальные параметры"><div className="settings-grid"><section className="panel settings-card"><h2>Основная информация</h2><Field label="Название магазина" value={value.name} setValue={name => setValue({ ...value, name })} required /><Field label="Краткое описание" value={value.description} setValue={description => setValue({ ...value, description })} /><SelectField label="Город по умолчанию" value={value.defaultCity} setValue={defaultCity => setValue({ ...value, defaultCity })} options={cityNames} /><button className="admin-primary" onClick={() => window.alert("Настройки сохранены локально")}>Сохранить</button></section><section className="panel settings-card"><h2>Предпросмотр</h2><div className="settings-preview"><strong>{value.name || "iCenter"}</strong><span>{value.description || "Описание не задано"}</span><small>Город по умолчанию: {value.defaultCity}</small></div></section></div></Shell>; }

function MediaPage() { const [items, setItems] = useDemoStore("media", initialMedia); const [query, setQuery] = useState(""); const [kind, setKind] = useState("Все типы"); const [sort, setSort] = useState("name"); const [selected, setSelected] = useState<Media | null>(null); const [error, setError] = useState(""); const filtered = items.filter(x => x.name.toLowerCase().includes(query.toLowerCase()) && (kind === "Все типы" || kind === x.type)).sort((a, b) => sort === "name" ? a.name.localeCompare(b.name) : b.id.localeCompare(a.id)); const upload = (file: File | undefined) => { if (!file) return; if (!file.type.startsWith("image/") || !/\.(png|jpe?g|webp|gif)$/i.test(file.name)) { setError("Допустимы только изображения PNG, JPG, WebP или GIF."); return; } if (file.size > 1024 * 1024) { setError("В локальном демо можно загрузить файл размером до 1 МБ."); return; } const reader = new FileReader(); reader.onerror = () => setError("Не удалось прочитать файл."); reader.onload = () => { setItems(prev => [{ id: `media-${Date.now()}`, name: file.name, url: String(reader.result), alt: "", description: "", type: "image", used: false }, ...prev]); setError(""); }; reader.readAsDataURL(file); }; return <Shell title="Медиа" subtitle="Локальное демо-хранилище изображений"><div className="media-upload-row"><label className="admin-primary upload-control"><Plus size={16} />Загрузить файл<input type="file" accept="image/png,image/jpeg,image/webp,image/gif" onChange={e => { upload(e.target.files?.[0]); e.currentTarget.value = ""; }} /></label><span>PNG, JPG, WebP или GIF · до 1 МБ</span></div><Toolbar query={query} setQuery={setQuery} placeholder="Поиск по названию файла..."><select value={kind} onChange={e => setKind(e.target.value)}><option>Все типы</option><option value="image">Изображения</option><option value="document">Документы</option></select><select value={sort} onChange={e => setSort(e.target.value)}><option value="name">По имени</option><option value="date">Сначала новые</option></select></Toolbar>{error && <p className="form-error" role="alert">{error}</p>}{filtered.length ? <div className="media-grid">{filtered.map(item => <article className="panel media-card" key={item.id} onClick={() => setSelected(item)}><img src={item.url} alt={item.alt || item.name} /><strong>{item.name}</strong><span>{item.type === "image" ? "Изображение" : "Документ"} · {item.used ? "используется" : "не используется"}</span></article>)}</div> : <Empty />}{selected && <Modal title="Информация о файле" close={() => setSelected(null)} save={() => { setItems(prev => prev.map(x => x.id === selected.id ? selected : x)); setSelected(null); }}><img className="media-detail-image" src={selected.url} alt={selected.alt || selected.name} /><Field label="Имя файла" value={selected.name} setValue={name => setSelected({ ...selected, name })} /><Field label="Альтернативный текст" value={selected.alt} setValue={alt => setSelected({ ...selected, alt })} /><Field label="Описание" value={selected.description} setValue={description => setSelected({ ...selected, description })} />{!selected.used ? <button className="admin-danger" onClick={() => { if (window.confirm("Удалить файл локально?")) { setItems(prev => prev.filter(x => x.id !== selected.id)); setSelected(null); } }}>Удалить файл</button> : <p className="admin-note">Удаление заблокировано: файл помечен как используемый.</p>}<p className="admin-note">Файл хранится только в localStorage текущего браузера; серверного хранилища нет.</p></Modal>}</Shell>; }

export default function AdminSection({ params }: { params: { slug: string[] } }) { const page = params.slug[0]; if (page === "requests") return <RequestsPage />; if (page === "products") return <ProductsStudio />; if (page === "categories") return <CategoriesPage />; if (page === "brands") return <BrandsPage />; if (page === "colors") return <ColorsPage />; if (page === "product-types") return <ProductTypesStudio />; if (page === "cities") return <CitiesPage />; if (page === "banners") return <BannersPage />; if (page === "best-offers") return <BestOffersStudio />; if (page === "employees") return <EmployeesPage />; if (page === "settings") return <SettingsPage />; if (page === "media") return <MediaPage />; return <Shell title="Раздел" subtitle="Демонстрационный экран"><Empty /></Shell>; }
